function D({registerIndicator:x,nulls:u}){x({id:"oa-decaychannel",name:"Decay Min-Max Channel (DECAYCHANNEL)",category:"Channels",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:100,min:1,max:2e3,step:1}],plots:[{key:"highest",type:"line",title:"Decaying High",style:{color:"#ffeb3b",lineWidth:2}},{key:"lowest",type:"line",title:"Decaying Low",style:{color:"#ffeb3b",lineWidth:2}}],fills:[{between:["highest","lowest"],colorUp:"#2962ff",colorDown:"#2962ff",opacity:.1}],calc(o,F){const c=Math.max(1,Math.floor(Number(F.period)||100)),y=Math.log(2)/c,b=new Array(o.length).fill(NaN),p=new Array(o.length).fill(NaN),d=new Array(c).fill(NaN),M=new Array(c).fill(NaN);let e=NaN,i=NaN,m=0,f=0;for(let t=0;t<o.length;t++){const r=o[t].high,s=o[t].low,w=t%c;d[w]=r,M[w]=s;let n=NaN,l=NaN,g=0;for(let a=0;a<c;a++){const h=d[a],N=M[a];!Number.isFinite(h)||!Number.isFinite(N)||(n=Number.isFinite(n)?Math.max(n,h):h,l=Number.isFinite(l)?Math.min(l,N):N,g+=1)}if(!Number.isFinite(e)||!Number.isFinite(i))e=Number.isFinite(n)?n:r,i=Number.isFinite(l)?l:s,m=0,f=0;else if(Number.isFinite(r)&&r>=e?(e=r,m=0):m+=1,Number.isFinite(s)&&s<=i?(i=s,f=0):f+=1,g>0){const a=(e+i)/2,h=1-Math.exp(-y*m),N=1-Math.exp(-y*f);e=e-h*(e-a),i=i-N*(i-a),Number.isFinite(n)&&(e=Math.min(e,n)),Number.isFinite(l)&&(i=Math.max(i,l))}b[t]=e,p[t]=i}return{highest:u(b),lowest:u(p)}}})}export{D as default};
